from pathlib import Path
import os,json,stat,shutil,subprocess
D='AlazHarness-D3B-P71C'
assert os.environ.get('WSL_DISTRO_NAME')==D and Path('/etc/alaz-p71c-lab-id').read_text().strip()==D
assert os.getuid()==os.geteuid()==0 and not Path('/mnt/c/Windows').exists()
assert Path('/proc/self/uid_map').read_text().split()==['0','0','4294967295']
report={'uid':os.getuid(),'gid':os.getgid(),'distro':D,'uname':list(os.uname()),'tools':{},'loopNodes':[],'cgroupRoot':{},'mountNamespace':os.readlink('/proc/self/ns/mnt')}
for name in ('unshare','mount','umount','losetup','mkfs.ext4','findmnt'):
 path=shutil.which(name);report['tools'][name]=path
 if path:
  s=Path(path).resolve().stat();report['tools'][name]={'path':path,'resolved':str(Path(path).resolve()),'uid':s.st_uid,'mode':oct(stat.S_IMODE(s.st_mode))}
for p in sorted(Path('/dev').glob('loop*')):
 s=p.stat();report['loopNodes'].append({'name':p.name,'mode':oct(s.st_mode),'dev':[os.major(s.st_rdev),os.minor(s.st_rdev)]})
report['loopSysNames']=[p.name for p in sorted(Path('/sys/class/block').glob('loop*'))]
for name in ('cgroup.controllers','cgroup.type','cgroup.events'):
 p=Path('/sys/fs/cgroup')/name;report['cgroupRoot'][name]=p.read_text() if p.is_file() else None
report['privateNewPathsAbsent']={str(p):not p.exists() for p in (Path('/opt/alaz-s101'),Path('/srv/alaz-s101'))}
print(json.dumps(report))
